\[
\begin{aligned}
\delta H&=0,\quad \delta^2H>0 &&\text{at fixed }S,p,N_i,\\
\delta F&=0,\quad \delta^2F>0 &&\text{at fixed }T,V,N_i,\\
\delta G&=0,\quad \delta^2G>0 &&\text{at fixed }T,p,N_i.
\end{aligned}
\tag*{[3]}
\]
